def P(s,style="Bodyx"): return Paragraph(s,styles[style])
def bullets(items): return [P("- "+x,"Bulletx") for x in items]
def mk_table(rows,widths):
    rr=[[P(str(c),"Head" if i==0 else "Cell") for c in row] for i,row in enumerate(rows)]
    t=Table(rr,colWidths=widths,repeatRows=1,hAlign="LEFT")
    cmd=[("VALIGN",(0,0),(-1,-1),"TOP"),("GRID",(0,0),(-1,-1),.3,colors.HexColor("#CBD5E1")),("LEFTPADDING",(0,0),(-1,-1),5),("RIGHTPADDING",(0,0),(-1,-1),5),("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4),("BACKGROUND",(0,0),(-1,0),NAVY)]
    for i in range(1,len(rows)):
        if i%2==0: cmd.append(("BACKGROUND",(0,i),(-1,i),colors.HexColor("#F8FAFC")))
    t.setStyle(TableStyle(cmd)); return t

class Flow(Flowable):
    def __init__(self,labels,w=170*mm): self.labels=labels; self.width=w; self.height=max(28*mm,len(labels)*14*mm)
    def draw(self):
        c=self.canv; bw=52*mm; bh=9*mm; gap=4*mm; x=(self.width-bw)/2
        for i,label in enumerate(self.labels):
            y=self.height-(i+1)*(bh+gap)+gap
            c.setFillColor(PALE if i%2==0 else colors.HexColor("#FFF7ED")); c.setStrokeColor(BLUE if i%2==0 else ORANGE)
            c.roundRect(x,y,bw,bh,5,fill=1,stroke=1); c.setFillColor(INK); c.setFont("Helvetica-Bold",7.5); c.drawCentredString(self.width/2,y+bh/2-2.2,label)
            if i<len(self.labels)-1:
                c.setStrokeColor(MUTED); c.line(self.width/2,y-1,self.width/2,y-gap+1)
                c.line(self.width/2,y-gap+1,self.width/2-2,y-gap+4); c.line(self.width/2,y-gap+1,self.width/2+2,y-gap+4)

def footer(c,doc):
    c.saveState(); c.setStrokeColor(colors.HexColor("#CBD5E1")); c.line(16*mm,13*mm,194*mm,13*mm)
    c.setFont("Helvetica",7.5); c.setFillColor(MUTED); c.drawString(16*mm,8*mm,"SmartHire project deep dive - source inspection report"); c.drawRightString(194*mm,8*mm,f"Page {doc.page}"); c.restoreState()

